const settings = $input.first().json;
const tickers = String(settings.tickers || '')
  .split(',')
  .map((ticker) => ticker.trim().toUpperCase())
  .filter(Boolean);

if (tickers.length === 0) {
  throw new Error('Monitor settings has no tickers. Put at least one symbol in tickers, separated by commas.');
}

const invalid = tickers.filter((ticker) => !/^[A-Z][A-Z0-9.\-]{0,9}$/.test(ticker));
if (invalid.length > 0) {
  throw new Error('These do not look like ticker symbols: ' + invalid.join(', ') + '. Use uppercase symbols such as NVDA.');
}

return tickers.map((ticker) => ({
  json: {
    ticker,
    lookbackDays: settings.lookbackDays,
    articleCount: settings.articleCount,
  },
}));

