const settings = $('Monitor settings').first().json;
const staticData = $getWorkflowStaticData('global');
const alerted = new Set(Array.isArray(staticData.alertedUrls) ? staticData.alertedUrls : []);
const clean = (value) => String(value ?? '').replace(/[<>|]/g, '').trim();

const labels = {
  earnings: 'Earnings',
  guidance: 'Guidance',
  regulatory: 'Regulatory',
  partnership: 'Partnership',
  supply_chain: 'Supply chain',
  executive_change: 'Executive change',
  rating_change: 'Rating change',
  other_material: 'Material news',
};

const sections = [];

for (const item of $input.all()) {
  const output = item.json.output || {};
  const ticker = clean(output.ticker).toUpperCase() || 'WATCHLIST';
  const materialItems = Array.isArray(output.items) ? output.items : [];
  const lines = [];

  for (const story of materialItems) {
    const url = String(story?.url ?? '').trim();
    if (!url || alerted.has(url)) continue;
    alerted.add(url);

    const headline = clean(story.headline) || url;
    const publisher = clean(story.publisher);
    const summary = clean(story.summary);
    const label = labels[story.event_type] || 'Material news';

    let line = '• *' + label + '* — <' + url + '|' + headline + '>';
    if (publisher) line += ' (' + publisher + ')';
    if (summary) line += '\n    ' + summary;
    lines.push(line);
  }

  if (lines.length > 0) {
    sections.push('*' + ticker + '*\n' + lines.join('\n'));
  }
}

// Remember what was alerted, capped so static data stays small.
staticData.alertedUrls = Array.from(alerted).slice(-500);

const alertText = ':rotating_light: *Watchlist news alert*\n\n' + sections.join('\n\n');

return [{
  json: {
    hasAlerts: sections.length > 0,
    alertText,
    slackChannel: settings.slackChannel,
  },
}];
